#!/usr/bin/env python3# -*- coding: utf-8 -*-"""Subprocess helpers for constructing MD systems from the GUI.The GUI runs in a lightweight environment. Scientific construction isperformed by a separate Python interpreter belonging to the fulliPHAsimulator environment."""from __future__ import annotationsimport jsonfrom pathlib import Pathfrom gui.config import (    PROJECT_ROOT,    STRUCTURE_DATABASE,)from gui.subprocess_helpers import (    build_iphasimulator_environment,    run_subprocess,    validate_iphasimulator_python,)def get_available_built_polymers(    structure_database: str | Path = STRUCTURE_DATABASE,) -> list[str]:    """    Return polymers that contain complete Amber build files.    """    built_polymers_dir = (        Path(structure_database)        / "built_PHAs"    )    if not built_polymers_dir.exists():        return []    available_polymers = []    for polymer_dir in built_polymers_dir.iterdir():        if not polymer_dir.is_dir():            continue        polymer_name = polymer_dir.name        amber_dir = polymer_dir / "amber"        required_files = [            amber_dir / f"{polymer_name}.pdb",            amber_dir / f"{polymer_name}.prmtop",            amber_dir / f"{polymer_name}.rst7",        ]        if all(path.is_file() and path.stat().st_size > 0 for path in required_files):            available_polymers.append(                polymer_name            )    return sorted(        available_polymers    )def get_built_polymer_choices(structure_database=STRUCTURE_DATABASE):    """Group complete builds by name prefix and numeric chain length.    Preserve the full prefix for copolymers, including their sequence, so    different compositions cannot silently resolve to the same build.    """    choices = {}    for name in get_available_built_polymers(structure_database):        polymer_type, separator, length = name.rpartition("_")        if separator and length.isdigit() and int(length) > 0:            choices.setdefault(polymer_type, {})[int(length)] = name    return {kind: dict(sorted(lengths.items())) for kind, lengths in sorted(choices.items())}def get_incomplete_polymer_builds(structure_database=STRUCTURE_DATABASE):    """Explain why a build directory is not ready for MD system creation."""    root = Path(structure_database) / "built_PHAs"    if not root.is_dir():        return {}    incomplete = {}    for folder in sorted(root.iterdir()):        if not folder.is_dir():            continue        missing = []        for extension in ("pdb", "prmtop", "rst7"):            path = folder / "amber" / f"{folder.name}.{extension}"            if not path.is_file():                missing.append(f".{extension} missing")            elif path.stat().st_size == 0:                missing.append(f".{extension} empty")        if missing:            incomplete[folder.name] = ", ".join(missing)    return incompletedef run_md_system_build_subprocess(    *,    system_type: str,    build_settings: dict,):    """    Run one MD-system build in the scientific environment.    Parameters    ----------    system_type : str        One of:        - dry        - solvated        - solvated_ions        - melt    build_settings : dict        Settings forwarded to the selected backend function.    Returns    -------    subprocess.CompletedProcess        Captured subprocess result.    """    allowed_types = {        "dry",        "solvated",        "solvated_ions",        "melt",    }    if system_type not in allowed_types:        raise ValueError(            f"Unsupported MD system type: {system_type}"        )    backend_code = r"""import jsonimport sysimport tracebacksystem_type = sys.argv[1]settings = json.loads(sys.argv[2])try:    if system_type == "dry":        from iphasimulator.build_single_PHA_systems import build_dry_PHA        result = build_dry_PHA(            polymer_name=settings["polymer_name"],            root_dir=settings["root_dir"],            forcefield=settings["forcefield"],            box_radius=float(settings["box_radius"]),        )    elif system_type == "solvated":        from iphasimulator.build_single_PHA_systems import build_solvated_PHA        result = build_solvated_PHA(            polymer_name=settings["polymer_name"],            root_dir=settings["root_dir"],            forcefield=settings["forcefield"],            water_leaprc=settings["water_leaprc"],            water_box=settings["water_box"],            box_radius=float(settings["box_radius"]),        )    elif system_type == "solvated_ions":        from iphasimulator.build_single_PHA_systems import (            build_solvated_PHA_ions,        )        result = build_solvated_PHA_ions(            polymer_name=settings["polymer_name"],            root_dir=settings["root_dir"],            forcefield=settings["forcefield"],            water_leaprc=settings["water_leaprc"],            water_box=settings["water_box"],            box_radius=float(settings["box_radius"]),            salt=settings["salt"],            pos_ion=settings["positive_ion"],            neg_ion=settings["negative_ion"],            ion_conc=float(settings["ion_concentration"]),        )    elif system_type == "melt":        from iphasimulator.pha_melt_builder import PHAMeltBuilder        builder = PHAMeltBuilder(            root_dir=settings["root_dir"],        )        result = builder.generate_polymer_melt(            polymer_names=settings["polymer_names"],            number_of_polymers=[                int(value)                for value in settings["number_of_polymers"]            ],            density=float(settings["density"]),        )    else:        raise ValueError(            f"Unsupported MD system type: {system_type}"        )    print("\nMD_SYSTEM_BUILD_RESULT")    print(        json.dumps(            result,            default=str,            indent=2,        )    )except Exception:    print(        "\nMD system build failed.",        file=sys.stderr,    )    traceback.print_exc(        file=sys.stderr    )    sys.exit(1)"""    python_path = validate_iphasimulator_python()    command = [        str(python_path),        "-c",        backend_code,        system_type,        json.dumps(            build_settings        ),    ]    return run_subprocess(        command=command,        workdir=PROJECT_ROOT,        environment=build_iphasimulator_environment(),    )def build_dry_system_subprocess(    *,    polymer_name: str,    forcefield: str,    box_radius: float,):    return run_md_system_build_subprocess(        system_type="dry",        build_settings={            "root_dir": str(STRUCTURE_DATABASE),            "polymer_name": polymer_name,            "forcefield": forcefield,            "box_radius": float(box_radius),        },    )def build_solvated_system_subprocess(    *,    polymer_name: str,    forcefield: str,    water_leaprc: str,    water_box: str,    box_radius: float,):    return run_md_system_build_subprocess(        system_type="solvated",        build_settings={            "root_dir": str(STRUCTURE_DATABASE),            "polymer_name": polymer_name,            "forcefield": forcefield,            "water_leaprc": water_leaprc,            "water_box": water_box,            "box_radius": float(box_radius),        },    )def build_solvated_ions_system_subprocess(    *,    polymer_name: str,    forcefield: str,    water_leaprc: str,    water_box: str,    box_radius: float,    salt: str,    positive_ion: str,    negative_ion: str,    ion_concentration: float,):    return run_md_system_build_subprocess(        system_type="solvated_ions",        build_settings={            "root_dir": str(STRUCTURE_DATABASE),            "polymer_name": polymer_name,            "forcefield": forcefield,            "water_leaprc": water_leaprc,            "water_box": water_box,            "box_radius": float(box_radius),            "salt": salt,            "positive_ion": positive_ion,            "negative_ion": negative_ion,            "ion_concentration": float(                ion_concentration            ),        },    )def build_melt_system_subprocess(    *,    polymer_names: list[str],    number_of_polymers: list[int],    density: float,):    return run_md_system_build_subprocess(        system_type="melt",        build_settings={            "root_dir": str(STRUCTURE_DATABASE),            "polymer_names": list(                polymer_names            ),            "number_of_polymers": [                int(value)                for value in number_of_polymers            ],            "density": float(density),        },    )def get_water_model_settings(    water_model: str,) -> tuple[str, str]:    settings = {        "TIP3P": (            "water.tip3p",            "TIP3PBOX",        ),    }    if water_model not in settings:        raise ValueError(            f"Unsupported water model: {water_model}"        )    return settings[water_model]def get_salt_name(    positive_ion: str,    negative_ion: str,) -> str:    salts = {        ("K+", "Cl-"): "KCl",        ("Na+", "Cl-"): "NaCl",    }    ion_pair = (        positive_ion,        negative_ion,    )    if ion_pair not in salts:        raise ValueError(            "Unsupported ion combination: "            f"{positive_ion} / {negative_ion}"        )    return salts[ion_pair]